import { cloneTexture2D, getOrCreateSampler, loadKtx2Texture2D, loadTexture2D, SceneContext, Texture2D } from "@babylonjs/lite";

import { getLoadableUrl } from "../tools/request";
import { _getKtx2TextureName, getTextureUrlForQuality, isUsingKtx2CompressedTextures } from "../tools/texture";

import type { SceneLoaderQualitySelector } from "./loader";

/**
 * Defines the list of image extensions for which a KTX2 version is generated by the editor when compressed textures are enabled.
 */
export const ktx2SupportedExtensions: string[] = [".png", ".jpg", ".jpeg", ".bmp"];

export interface ISerializedTextureLoadOptions {
	/**
	 * Defines wether or not the GPU decodes the colors of the texture from sRGB to linear when sampled (sRGB texture).
	 * It is always the case for the textures Babylon.js loads in a sRGB buffer (see `isSerializedTextureInSrgbBuffer`).
	 */
	srgb?: boolean;
	/**
	 * Defines wether or not the texture can be replaced by its KTX2 version when compressed textures are enabled.
	 * @default true
	 */
	allowCompressed?: boolean;
	/**
	 * Defines wether or not the quality of the scene applies to the texture.
	 * @default true
	 */
	allowQuality?: boolean;
}

/**
 * Defines a texture loaded from its serialized data and the function to call to assign it, so it can be reloaded
 * later with another quality.
 * @see applyTexturesQuality
 * @internal
 */
export interface _ITextureSlot {
	data: any;
	rootUrl: string;
	options: ISerializedTextureLoadOptions;
	quality: SceneLoaderQualitySelector;
	assign: (texture: Texture2D) => void;
	/**
	 * Defines the optional function loading the texture for the given quality, used instead of loading the texture
	 * as it is (ie. repacked textures).
	 */
	load?: (quality: SceneLoaderQualitySelector) => Promise<Texture2D | null>;
}

const sceneTextureSlots = new WeakMap<SceneContext, _ITextureSlot[]>();

/**
 * Returns wether or not Babylon.js loads the given serialized texture in a sRGB buffer (`_useSRGBBuffer`, set by the
 * glTF loader on the color textures): the GPU decodes its colors from sRGB to linear when sampled, whatever the gamma
 * space of the texture.
 * @param data defines the serialized data of the texture.
 */
export function isSerializedTextureInSrgbBuffer(data: any): boolean {
	return data?._useSRGBBuffer === true;
}

/**
 * Returns wether or not the materials of Babylon.js decode the colors of the given serialized color texture (albedo,
 * emissive, reflectivity, etc.) from gamma space to linear in their shaders (`toLinearSpace`): the texture is in gamma
 * space and not loaded in a sRGB buffer. The shaders approximate the sRGB curve by a 2.2 power, darker in the dark tones
 * than the exact curve the GPU uses to decode the sRGB textures.
 * @param data defines the serialized data of the texture.
 */
export function isSerializedTextureInGammaSpace(data: any): boolean {
	return (data?.gammaSpace ?? true) !== false && !isSerializedTextureInSrgbBuffer(data);
}

/**
 * Converts the given Babylon.js wrap mode to the WebGPU address mode.
 */
export function getAddressMode(wrapMode: number | undefined): GPUAddressMode {
	switch (wrapMode) {
		case 0:
			return "clamp-to-edge";
		case 2:
			return "mirror-repeat";
		default:
			return "repeat";
	}
}

/**
 * Converts the given Babylon.js sampling mode to the WebGPU min and mag filters.
 */
export function getFilterModes(samplingMode: number | undefined): { magFilter: GPUFilterMode; minFilter: GPUFilterMode } {
	switch (samplingMode) {
		case 1: // NEAREST_SAMPLINGMODE
		case 4: // NEAREST_NEAREST_MIPNEAREST
		case 8: // NEAREST_NEAREST
			return { magFilter: "nearest", minFilter: "nearest" };
		case 5: // NEAREST_LINEAR_MIPNEAREST
		case 6: // NEAREST_LINEAR_MIPLINEAR
		case 7: // NEAREST_LINEAR
			return { magFilter: "nearest", minFilter: "linear" };
		case 9: // LINEAR_NEAREST_MIPNEAREST
		case 10: // LINEAR_NEAREST_MIPLINEAR
		case 12: // LINEAR_NEAREST
			return { magFilter: "linear", minFilter: "nearest" };
		default:
			return { magFilter: "linear", minFilter: "linear" };
	}
}

/**
 * Returns the URL of the texture described by the given serialized data, according to the quality and to the
 * compressed textures configuration.
 * @param data defines the serialized data of the texture.
 * @param rootUrl defines the root url of the scene.
 * @param quality defines the quality of the texture to load.
 * @param options defines the options of the texture.
 */
export function getSerializedTextureUrl(data: any, rootUrl: string, quality: SceneLoaderQualitySelector, options?: ISerializedTextureLoadOptions): string | null {
	let name = data?.name as string | undefined;
	if (!name) {
		return null;
	}

	if (name.startsWith("data:") || name.startsWith("blob:")) {
		return name;
	}

	if (options?.allowQuality !== false) {
		name = getTextureUrlForQuality(data, quality) as string;
	}

	const extension = name.substring(name.lastIndexOf(".")).toLowerCase();
	if (isUsingKtx2CompressedTextures() && options?.allowCompressed !== false && ktx2SupportedExtensions.includes(extension)) {
		name = _getKtx2TextureName(name);
	}

	return name.indexOf("://") > 0 ? name : `${rootUrl}${name}`;
}

/**
 * Computes the UV transform of Babylon Lite equivalent to the texture matrix of Babylon.js for the given
 * serialized texture. Babylon.js rotates the UVs around the rotation center of the texture (0.5, 0.5 by default)
 * while Babylon Lite rotates them around (0, 0): the offsets are computed so both transforms match.
 * The transforms are identical as long as the scale is uniform when the texture is rotated.
 * @param data defines the serialized data of the texture.
 */
export function getSerializedTextureTransform(data: any): Pick<Texture2D, "uScale" | "vScale" | "uOffset" | "vOffset" | "uAng"> {
	const uScale = data.uScale ?? 1;
	const vScale = data.vScale ?? 1;
	const uOffset = data.uOffset ?? 0;
	const vOffset = data.vOffset ?? 0;
	const angle = data.wAng ?? 0;

	if (!angle) {
		return { uScale, vScale, uOffset, vOffset, uAng: 0 };
	}

	const uCenter = data.uRotationCenter ?? 0.5;
	const vCenter = data.vRotationCenter ?? 0.5;

	const cos = Math.cos(angle);
	const sin = Math.sin(angle);

	// Same as Babylon.js Texture._prepareRowForTextureGeneration for the (0, 0) UV coordinates.
	const x = -uCenter * uScale;
	const y = -vCenter * vScale;

	return {
		uScale,
		vScale,
		uAng: angle,
		uOffset: x * cos - y * sin + uCenter * uScale + uOffset,
		vOffset: x * sin + y * cos + vCenter * vScale + vOffset,
	};
}

/**
 * Returns wether or not the given serialized texture has a UV transform (scale, offset or rotation).
 * @param data defines the serialized data of the texture.
 */
export function hasSerializedTextureTransform(data: any): boolean {
	return (data.uScale ?? 1) !== 1 || (data.vScale ?? 1) !== 1 || (data.uOffset ?? 0) !== 0 || (data.vOffset ?? 0) !== 0 || (data.wAng ?? 0) !== 0;
}

/**
 * Returns a texture sharing the GPU resources of the given texture with the UV transform and the UV set of the
 * given serialized texture, or the given texture itself when it has no transform and uses the first UV set.
 * Babylon Lite caches the loaded textures by URL: each use of a texture with a transform needs its own wrapper.
 * @param texture defines the reference to the loaded texture.
 * @param data defines the serialized data of the texture.
 */
export function applySerializedTextureTransform(texture: Texture2D, data: any): Texture2D {
	const hasTransform = hasSerializedTextureTransform(data);
	if (!hasTransform && !data.coordinatesIndex) {
		return texture;
	}

	return cloneTexture2D(texture, {
		...(hasTransform ? { ...getSerializedTextureTransform(data), _hasTx: true as const } : {}),
		_texCoord: data.coordinatesIndex === 1 ? 1 : 0,
	});
}

/**
 * Loads the texture located at the given URL using the right Babylon Lite loader (KTX2 or images).
 * @param scene defines the reference to the scene the texture belongs to.
 * @param url defines the url of the texture to load.
 * @param data defines the serialized data of the texture (sampling and wrap modes, invertY, etc.).
 * @param options defines the options of the texture.
 */
export async function loadTextureFromUrl(scene: SceneContext, url: string, data: any, options?: ISerializedTextureLoadOptions): Promise<Texture2D> {
	const engine = scene.surface.engine;
	const loadableUrl = await getLoadableUrl(url);

	const srgb = (options?.srgb ?? false) || isSerializedTextureInSrgbBuffer(data);
	const { magFilter, minFilter } = getFilterModes(data?.samplingMode);
	const addressModeU = getAddressMode(data?.wrapU);
	const addressModeV = getAddressMode(data?.wrapV);

	if (url.toLowerCase().endsWith(".ktx2")) {
		const texture = await loadKtx2Texture2D(engine, loadableUrl, srgb);

		// KTX2 textures come with their default sampler.
		if (addressModeU !== "repeat" || addressModeV !== "repeat" || magFilter !== "linear" || minFilter !== "linear") {
			const clone = cloneTexture2D(texture, {});
			clone.sampler = getOrCreateSampler(engine, {
				addressModeU,
				addressModeV,
				magFilter,
				minFilter,
				mipmapFilter: minFilter === "nearest" ? "nearest" : "linear",
			});

			return clone;
		}

		return texture;
	}

	return loadTexture2D(engine, loadableUrl, {
		srgb,
		invertY: data?.invertY ?? true,
		mipMaps: !data?.noMipmap,
		addressModeU,
		addressModeV,
		magFilter,
		minFilter,
	});
}

/**
 * Loads the texture described by the given serialized data (as saved by Babylon.js `Texture.serialize`), applying
 * the loading quality of the scene and the compressed textures configuration.
 * @param scene defines the reference to the scene the texture belongs to.
 * @param rootUrl defines the root url of the scene.
 * @param data defines the serialized data of the texture.
 * @param options defines the options of the texture.
 * @param assign defines the optional function called with the loaded texture, called again when the quality of the textures changes.
 * @returns the loaded texture or null if the texture can't be loaded (cube textures, render targets, etc.).
 */
export async function loadSerializedTexture(
	scene: SceneContext,
	rootUrl: string,
	data: any,
	options?: ISerializedTextureLoadOptions,
	assign?: (texture: Texture2D) => void
): Promise<Texture2D | null> {
	if (!data || data.isCube || data.isRenderTarget || data.is3D || data.is2DArray) {
		return null;
	}

	const quality = scene.loadingTexturesQuality ?? "high";

	const url = getSerializedTextureUrl(data, rootUrl, quality, options);
	if (!url) {
		return null;
	}

	let texture: Texture2D;

	try {
		texture = await loadTextureFromUrl(scene, url, data, options);
	} catch (e) {
		console.error(`Failed to load texture "${url}".`, e);
		return null;
	}

	texture = applySerializedTextureTransform(texture, data);

	if (assign) {
		assign(texture);

		_registerTextureSlot(scene, {
			data,
			rootUrl,
			assign,
			quality,
			options: options ?? {},
		});
	}

	return texture;
}

/**
 * @internal
 * Registers the given texture slot so the texture is loaded again when the quality of the textures of the scene changes.
 */
export function _registerTextureSlot(scene: SceneContext, slot: _ITextureSlot): void {
	let slots = sceneTextureSlots.get(scene);
	if (!slots) {
		slots = [];
		sceneTextureSlots.set(scene, slots);
	}

	slots.push(slot);
}

/**
 * @internal
 * Reloads all the textures of the given scene with the given quality.
 */
export async function _reloadSceneTextures(scene: SceneContext, quality: SceneLoaderQualitySelector): Promise<void> {
	const slots = sceneTextureSlots.get(scene);
	if (!slots) {
		return;
	}

	await Promise.all(
		slots.map(async (slot) => {
			if (slot.quality === quality) {
				return;
			}

			const previousUrl = getSerializedTextureUrl(slot.data, slot.rootUrl, slot.quality, slot.options);
			const url = getSerializedTextureUrl(slot.data, slot.rootUrl, quality, slot.options);

			slot.quality = quality;

			if (!url || url === previousUrl) {
				return;
			}

			if (slot.load) {
				const texture = await slot.load(quality);
				if (texture) {
					slot.assign(texture);
				}
				return;
			}

			try {
				const texture = await loadTextureFromUrl(scene, url, slot.data, slot.options);
				slot.assign(applySerializedTextureTransform(texture, slot.data));
			} catch (e) {
				console.error(`Failed to load texture "${url}".`, e);
			}
		})
	);
}
